class Node:
    # Represents a single node in the BST
    def __init__(self, key):
        self.key = key          # Value stored in the node
        self.left = None        # Left child pointer
        self.right = None       # Right child pointer


class BinarySearchTree:
    # Binary Search Tree with insert, find and in-order traversal
    def __init__(self):
        self.root = None        # Root node of the tree, None if empty

    def insert(self, key):
        # Insert a new key into the BST
        new_node = Node(key)
        if self.root is None:
            # Tree is empty, new node becomes root
            self.root = new_node
            return

        current = self.root
        while True:
            if key < current.key:
                # Go to left subtree
                if current.left is None:
                    current.left = new_node
                    break
                current = current.left
            elif key > current.key:
                # Go to right subtree
                if current.right is None:
                    current.right = new_node
                    break
                current = current.right
            else:
                # Key already exists, do nothing
                break

    def find(self, key):
        # Search for a key and return the node if found
        current = self.root
        while current is not None:
            if key == current.key:
                return current   # Key found
            elif key < current.key:
                current = current.left
            else:
                current = current.right
        return None  # Key not found

    def _inorder(self, node, result):
        # Helper recursive in-order traversal: left, root, right
        if node is None:
            return
        self._inorder(node.left, result)   # Traverse left subtree
        result.append(node.key)            # Visit node
        self._inorder(node.right, result)  # Traverse right subtree

    def inorder_traversal(self):
        # Return list of keys in sorted order
        result = []
        self._inorder(self.root, result)
        return result
